  selected = linkedSignal(() => this.items()[0]);

  // the extended form: the previous value is available
  selectedKeepIfPossible = linkedSignal<Item[], Item | undefined>({
    source: this.items,
    computation: (items, previous) =>
      items.find((i) => i.id === previous?.value?.id) ?? items[0],
