```ts
@Component({
  selector: 'app-toggle',
  template: `<button (click)="toggle()" [disabled]="disabled">{{ value }}</button>`,
  providers: [
    { provide: NG_VALUE_ACCESSOR, useExisting: forwardRef(() => ToggleComponent), multi: true },
  ],
})
export class ToggleComponent implements ControlValueAccessor {
  value = false;
  disabled = false;
  private onChange: (v: boolean) => void = () => {};
  private onTouched = () => {};

  writeValue(v: boolean) { this.value = v; }          // form → component
  registerOnChange(fn: (v: boolean) => void) { this.onChange = fn; }
  registerOnTouched(fn: () => void) { this.onTouched = fn; }
  setDisabledState(is: boolean) { this.disabled = is; }

  toggle() {
    this.value = !this.value;
    this.onChange(this.value);                         // component → form
    this.onTouched();
  }
}
```

